125	// upgradeWebSocket hijacks the connection and writes the 101 response. Every
126	// precondition (method, cursor, session, permission, handshake headers) has
127	// already been checked by the caller; from here on failures are reported as
128	// WebSocket close frames rather than HTTP statuses.
129	func upgradeWebSocket(w http.ResponseWriter, r *http.Request) (*wsConn, error) {
130		hj, ok := w.(http.Hijacker)
131		if !ok {
132			return nil, errors.New("connection does not support hijacking")
133		}
134		conn, brw, err := hj.Hijack()
135		if err != nil {
136			return nil, err
137		}
138	
139		accept := secWebSocketAccept(r.Header.Get("Sec-WebSocket-Key"))
140		response := "HTTP/1.1 101 Switching Protocols\r\n" +
141			"Upgrade: websocket\r\n" +
142			"Connection: Upgrade\r\n" +
143			"Sec-WebSocket-Accept: " + accept + "\r\n\r\n"
144		if _, err := io.WriteString(conn, response); err != nil {
145			_ = conn.Close()
146			return nil, err
147		}
148		// Flush anything the HTTP layer buffered before the hijack.
149		if err := brw.Flush(); err != nil {
150			_ = conn.Close()
151			return nil, err
152		}
153		return &wsConn{conn: conn, br: brw.Reader}, nil
154	}
