156	// readFrame reads one RFC 6455 frame, unmasking client payloads.
157	func (c *wsConn) readFrame() (fin bool, opcode byte, payload []byte, err error) {
158		header := make([]byte, 2)
159		if _, err = io.ReadFull(c.br, header); err != nil {
160			return false, 0, nil, err
161		}
162		b0, b1 := header[0], header[1]
