164			return false, 0, nil, wsProtocolError("reserved bits must be zero")
165		}
166		fin = b0&wsFlagFin != 0
167		opcode = b0 & 0x0F
168		masked := b1&wsFlagMask != 0
169		length := int64(b1 & 0x7F)
