171		switch length {
172		case 126:
173			var ext [2]byte
174			if _, err = io.ReadFull(c.br, ext[:]); err != nil {
175				return false, 0, nil, err
176			}
177			length = int64(binary.BigEndian.Uint16(ext[:]))
178		case 127:
179			var ext [8]byte
180			if _, err = io.ReadFull(c.br, ext[:]); err != nil {
181				return false, 0, nil, err
182			}
183			length = int64(binary.BigEndian.Uint64(ext[:]))
184			if length < 0 {
185				return false, 0, nil, wsProtocolError("frame length too large")
186			}
187		}
188		if opcode == wsOpcodeClose && length > wsMaxControlPayload {
189			return false, 0, nil, wsProtocolError("close frame too large")
190		}
191		if opcode >= wsOpcodeClose && !fin {
192			return false, 0, nil, wsProtocolError("control frame must not be fragmented")
193		}
194		if length > wsMaxInboundMessage {
195			return false, 0, nil, wsProtocolError("frame too large")
196		}
197	
198		var mask [4]byte
199		if masked {
200			if _, err = io.ReadFull(c.br, mask[:]); err != nil {
201				return false, 0, nil, err
202			}
203		}
204		payload = make([]byte, length)
205		if length > 0 {
206			if _, err = io.ReadFull(c.br, payload); err != nil {
207				return false, 0, nil, err
208			}
209		}
210		if masked {
211			for i := range payload {
212				payload[i] ^= mask[i%4]
213			}
214		} else {
215			// RFC 6455 §5.1: a frame from a client MUST be masked.
216			return false, 0, nil, wsProtocolError("client frame is not masked")
217		}
218		return fin, opcode, payload, nil
219	}
220	
221	// ReadMessage returns the next complete data message, answering control
222	// frames inline: a ping is answered with a pong, a pong is ignored, and a
223	// close frame surfaces as ErrWebSocketClosed (the caller echoes it). Fragmented
224	// messages are reassembled in receive order.
