226		var assembled []byte
227		started := false
228		messageOpcode := byte(wsOpcodeText)
229	
230		for {
231			fin, frameOpcode, framePayload, frameErr := c.readFrame()
232			if frameErr != nil {
233				return 0, nil, frameErr
234			}
235	
236			switch frameOpcode {
