238				if !started {
239					return 0, nil, wsProtocolError("continuation frame without a start frame")
240				}
241				assembled = append(assembled, framePayload...)
242			case wsOpcodeText, wsOpcodeBinary:
243				if started {
244					return 0, nil, wsProtocolError("new data frame before the fragment finished")
245				}
246				started = true
247				messageOpcode = frameOpcode
248				assembled = append(assembled[:0], framePayload...)
249			case wsOpcodeClose:
250				closeErr := parseClosePayload(framePayload)
251				if writeErr := c.writeCloseResponse(framePayload); writeErr != nil {
252					_ = c.conn.Close()
253				}
254				return 0, nil, closeErr
255			case wsOpcodePing:
256				if len(framePayload) > wsMaxControlPayload {
257					return 0, nil, wsProtocolError("ping payload too large")
258				}
259				if pingErr := c.writeControl(wsOpcodePong, framePayload); pingErr != nil {
260					return 0, nil, pingErr
261				}
262				continue
