264				continue
265			default:
266				return 0, nil, wsProtocolError(fmt.Sprintf("unknown opcode %d", frameOpcode))
267			}
268	
269			if len(assembled) > wsMaxInboundMessage {
270				return 0, nil, wsProtocolError("message too large")
271			}
272			if fin {
273				return messageOpcode, assembled, nil
274			}
275		}
276	}
