278	func parseClosePayload(payload []byte) error {
279		if len(payload) == 0 {
280			return &wsCloseError{Code: wsCloseGoingAway, Reason: ""}
281		}
282		if len(payload) < 2 {
283			return wsProtocolError("close payload too short")
284		}
285		code := int(binary.BigEndian.Uint16(payload[:2]))
286		return &wsCloseError{Code: code, Reason: string(payload[2:])}
287	}
