)

// handleDocumentSubscribe is the document-level WebSocket change subscription,
// the session view's counterpart that needs no session:
//
//	GET /v1/documents/{documentID}/changes/subscribe?deviceId=D&cursor=N
//
// The calling device is declared by the deviceId query parameter; no new
// authentication is introduced. Validation is fixed and entirely pre-upgrade,
// writing nothing:
//
//  1. cursor must be a non-negative decimal integer and the request must carry
//     a valid WebSocket upgrade handshake (400 JSON otherwise; a malformed path
//     is a 400 JSON too),
//  2. the declared device must currently be registered — a missing or empty
//     deviceId is treated as an unregistered caller (404 JSON),
//  3. it must currently hold permission for the document (403 JSON).
//
// Everything after the upgrade is byte-for-byte the session subscription:
// committed changes past the starting cursor are paged out in cursor order as
// one {"id","deviceId","payload","cursor"} text frame per row, then live
// commits continue seamlessly. The connection is push-only, ends with 4403 on a
// later sticky revoke and with 1001 on a termination signal, and leaves no
// durable trace.
func handleDocumentSubscribe(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	// Handshake and parameter shape first: a bad cursor is a 400 even when the
	// device is also unknown, matching the fixed validation order.
	cursor, ok := parseSubscribeCursor(w, r)
	if !ok {
		return
	}
	if !checkWebSocketUpgrade(r) {
		writeError(w, http.StatusBadRequest, "a WebSocket upgrade handshake is required")
		return
	}

	// Device existence. A missing or empty deviceId is indistinguishable from
	// an unregistered one: 404 JSON, before any document content is observed.
	deviceID := r.URL.Query().Get("deviceId")
	if deviceID == "" {
		writeError(w, http.StatusNotFound, "device not found")
		return
	}
	exists, err := s.DeviceExists(deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up device")
		return
	}
	if !exists {
		writeError(w, http.StatusNotFound, "device not found")
		return
	}

	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	conn, err := upgradeWebSocket(w, r)
	if err != nil {
		// The 101 could not be written and the connection has been hijacked
		// (or is gone); no JSON error can be produced and nothing was
		// registered.
		return
	}

	// The post-upgrade connection shares the session subscription's exact
	// pump: catch-up paging, live fan-out, push-only inbound frames, 4403
	// revoke and 1001 shutdown.
	serveSubscription(r, s, conn, documentID, deviceID, cursor)
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"
	"time"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/push"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// subscribePageLimit is the page size used while replaying changes already
// committed after the subscription cursor. It matches the largest page the
// paginated read endpoint accepts, so catch-up and reads stay page-aligned.
const subscribePageLimit = 1000

// wsCloseEchoWait bounds how long a server-initiated close waits for the
// client's close echo before the deferred TCP teardown.
const wsCloseEchoWait = 500 * time.Millisecond

// handleSubscribe is the WebSocket document subscription mounted under the
// session view:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/changes/subscribe?cursor=N
//
// The subscription identity is entirely the existing session: the session's
// owning device is the only credential. Validation happens entirely before
// the 101 handshake and writes nothing:
//
//  1. cursor must be a non-negative decimal integer (400 JSON otherwise),
//  2. the request must carry a valid WebSocket upgrade handshake (400 JSON),
//  3. the session must currently exist (404 JSON),
//  4. its device must currently hold permission for the document (403 JSON).
//
// After the upgrade the server first sends every committed change with a
// cursor greater than the starting cursor — paged in cursor order, one text
// frame per record in the exact {"id","deviceId","payload","cursor"} shape of
// a paginated read row — then seamlessly continues with changes committed by
// any write path (batch post, merge, restore, replay). Frames are never
// reordered or coalesced; a later read from the last observed cursor returns
// the same rows. The connection is push-only: inbound data frames are read
// and discarded, only close/ping control frames are honored.
//
// A permission revoked after the upgrade ends the subscription with close
// code 4403 and no further frame follows; a termination signal ends every
// subscription with 1001. A client disconnect simply unregisters — like long
// polling, a subscription writes no change, cursor or other record.
func handleSubscribe(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	// Parameter shape first: a bad cursor is a 400 even when the session or
	// handshake is also bad, matching the session-scoped read ordering.
	cursor, ok := parseSubscribeCursor(w, r)
	if !ok {
		return
	}
	if !checkWebSocketUpgrade(r) {
		writeError(w, http.StatusBadRequest, "a WebSocket upgrade handshake is required")
		return
	}

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}
	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	conn, err := upgradeWebSocket(w, r)
	if err != nil {
		// The 101 response could not be written and the connection has been
		// hijacked (or is gone), so no JSON error can be produced. Nothing
		// was registered or written to the store.
		return
	}

	serveSubscription(r, s, conn, documentID, deviceID, cursor)
}

// parseSubscribeCursor validates the mandatory cursor query parameter: it
// must be present and a decimal non-negative integer. Negative, fractional
// and non-numeric values are a 400 JSON error; signs and adornments are
// rejected.
func parseSubscribeCursor(w http.ResponseWriter, r *http.Request) (int64, bool) {
	raw := r.URL.Query().Get("cursor")
	// parseCursorPath accepts only decimal digits (no sign, fraction or
	// exponent); a missing parameter is an empty raw and is rejected too.
	cursor, ok := parseCursorPath(raw)
	if !ok {
		writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
		return 0, false
	}
	return cursor, true
}

// serveSubscription runs one upgraded connection to completion. It registers
// before the first log read (a commit landing during catch-up is therefore
// never missed), then alternates a flush phase — drain every page of changes
// past the last sent cursor — and a park phase on the wake channel. A revoke
// is acted on only after the committed tail is flushed, so a commit that was
// authorized when it landed is still delivered ahead of the 4403. The method
// returns when the client leaves, permission is revoked or the store starts
// closing; the hijacked connection is closed on exit.
func serveSubscription(r *http.Request, s *app.App, conn *wsConn, documentID, deviceID string, cursor int64) {
	// Registration precedes the first read: the wake channel is buffered, so
	// a commit during a read leaves a pending wake that makes the next park
	// return immediately — no wake is lost. The revoked channel closes once
	// if access is withdrawn, and that event survives a racing re-grant.
	wakeCh, revokedCh, unregister := s.AddSubscription(documentID, deviceID)
	// The management-plane record makes this connection listable and
	// cancelable by its owning device. It is pure memory: removal is the only
	// teardown and it neither writes nor advances anything.
	managed := s.RegisterPush(deviceID, documentID, push.KindChanges, cursor)
	defer func() {
		unregister()
		s.UnregisterPush(managed.Info().ID)
		_ = conn.NetClose()
	}()

	clientGone := make(chan struct{})
	go func() {
		defer close(clientGone)
		for {
			if _, _, err := conn.ReadMessage(); err != nil {
				// A malformed frame ends the connection with the RFC
				// protocol-error code; a client close is already echoed
				// inside ReadMessage; a network drop needs no frame.
				var protoErr *wsProtocolErrorString
				if errors.As(err, &protoErr) {
					_ = conn.Close(wsCloseProtocolError, "protocol error")
				}
				return
			}
			// Push-only channel: an inbound data frame is read and
			// discarded; the client cannot mutate the log over it.
		}
	}()

	// checkEnd non-blockingly maps a closing store to 1001, an active device
	// cancel to 4410 and a sticky revoke to 4403; it returns true when the
	// subscription must end. A termination signal takes precedence: SIGTERM
	// must end every subscription with 1001 even if a cancel or a revoke is
	// also pending.
	checkEnd := func() bool {
		if s.Closing() {
			endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
			return true
		}
		select {
		case <-managed.Canceled():
			endSubscription(conn, clientGone, wsCloseSubscriptionCanceled, "subscription canceled")
			return true
		default:
		}
		select {
		case <-revokedCh:
			endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
			return true
		default:
		}
		return false
	}

	position := cursor
	first := true
	for {
		if !first {
			// Park until a commit, a sticky revoke or the termination signal
			// wakes us. r.Context() covers a non-shutdown cancel; the read
			// pump covers a client disconnect.
			select {
			case <-wakeCh:
				// Drain any coalesced follow-up signal as well; the flush
				// below reconciles every case by re-reading from the last
				// sent cursor.
				select {
				case <-wakeCh:
				default:
				}
			case <-managed.Canceled():
				if s.Closing() {
					endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
					return
				}
				endSubscription(conn, clientGone, wsCloseSubscriptionCanceled, "subscription canceled")
				return
			case <-revokedCh:
				if s.Closing() {
					endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
					return
				}
				endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
				return
			case <-clientGone:
				return
			case <-r.Context().Done():
				return
			}
			if s.Closing() {
				endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
				return
			}
		}
		first = false

		// Flush phase: page every change past position in cursor order. A
		// termination signal or a revoke is honored between pages/rows so a
		// large catch-up cannot delay the closing frame. A revoke arriving
		// while the final already-authorized tail is in flight is checked
		// after the inner loop, so that tail still goes out first.
		for {
			if checkEnd() {
				return
			}
			select {
			case <-clientGone:
				return
			case <-r.Context().Done():
				return
			default:
			}

			changes, _, err := s.ListChanges(documentID, position, subscribePageLimit)
			if err != nil {
				_ = conn.Close(wsCloseInternalError, "internal error")
				return
			}
			for i := range changes {
				if checkEnd() {
					return
				}
				raw, marshalErr := json.Marshal(changes[i])
				if marshalErr != nil {
					_ = conn.Close(wsCloseInternalError, "internal error")
					return
				}
				if writeErr := conn.WriteText(raw); writeErr != nil {
					return
				}
				position = changes[i].Cursor
			}
			if len(changes) < subscribePageLimit {
				break
			}
		}

		// Caught up. A revoke that arrived during the last page (its tail was
		// just flushed) now ends the subscription; otherwise loop and park.
		// Closing still wins over a pending revoke.
		if checkEnd() {
			return
		}
	}
}

// endSubscription sends the mandated closing frame and briefly waits for the
// read pump to observe the peer's close echo, so a graceful close reaches the
// client instead of being truncated by the deferred TCP teardown. It returns
// promptly if the peer is already gone; the caller's deferred NetClose drops
// the socket either way.
func endSubscription(conn *wsConn, clientGone <-chan struct{}, code int, reason string) {
	_ = conn.Close(code, reason)
	timer := time.NewTimer(wsCloseEchoWait)
	defer timer.Stop()
	select {
	case <-clientGone:
	case <-timer.C:
	}
}

package server

import (
	"bytes"
	"errors"
	"net/http"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/crdt"
	"github.com/alicegogogogogo/local-first-sync-service/internal/push"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// handleCRDTStateSubscribe is the WebSocket subscription to a document's
// merged CRDT state, mounted under the session view:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/crdt/state/subscribe
//
// The subscription identity is entirely the existing session: the session's
// owning device is the only credential and no new auth is introduced. The
// validation order is fixed and entirely pre-upgrade, writing nothing:
//
//  1. the request must be a GET carrying a valid WebSocket upgrade handshake
//     (400 JSON otherwise; a malformed path is a 400 JSON too),
//  2. the session must currently exist (404 JSON),
//  3. its device must currently hold permission for the document (403 JSON).
//
// After the upgrade the server first pushes the current merged state; a
// document without any CRDT operation yet sends nothing and waits silently
// until its first state appears. From then on every commit that actually
// changes the merge — a counter's per-device maximum advancing, the set union
// growing, the register's winning value changing — is pushed as one text
// frame in transaction-commit order.
// Idempotent repeats, rejected regressions and wholly invalid batches change
// no state and produce no frame; re-adding an existing set element pushes
// nothing either.
//
// Each message is one text frame whose payload is byte-for-byte the state
// read endpoint's body: compact single-line JSON with the keys in type, value
// order, terminated by a newline. The connection is push-only: inbound data
// frames are read and discarded, ping is answered with pong. A permission
// revoke after the upgrade ends the subscription with close code 4403 —
// stickily, a re-grant never revives this connection — and a termination
// signal ends every subscription with 1001. Subscriptions are not persisted;
// after a restart a fresh subscription immediately receives the consistent
// current merged state.
func handleCRDTStateSubscribe(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	if !checkWebSocketUpgrade(r) {
		writeError(w, http.StatusBadRequest, "a WebSocket upgrade handshake is required")
		return
	}

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}
	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	conn, err := upgradeWebSocket(w, r)
	if err != nil {
		// The 101 could not be written and the connection has been hijacked
		// (or is gone); no JSON error can be produced and nothing was
		// registered.
		return
	}

	serveCRDTStateSubscription(r, s, conn, documentID, deviceID)
}

// serveCRDTStateSubscription runs one upgraded CRDT-state connection to
// completion. Registration and the initial state read are one atomic step in
// the store, so a state-changing commit lands either inside that initial
// state or in the subscription's queue: the first frame is the current merge
// and every later frame is strictly newer, in commit order. The method
// returns when the client leaves, permission is revoked or the store starts
// closing; the hijacked connection is closed on exit.
func serveCRDTStateSubscription(r *http.Request, s *app.App, conn *wsConn, documentID, deviceID string) {
	initial, sub, unregister, err := s.OpenCRDTSubscription(documentID, deviceID)
	if err != nil {
		_ = conn.Close(wsCloseInternalError, "internal error")
		_ = conn.NetClose()
		return
	}
	// The management-plane record makes this connection listable and
	// cancelable by its owning device. A state subscription carries no
	// starting cursor, so the recorded cursor is 0.
	managed := s.RegisterPush(deviceID, documentID, push.KindState, 0)
	defer func() {
		unregister()
		s.UnregisterPush(managed.Info().ID)
		_ = conn.NetClose()
	}()

	clientGone := make(chan struct{})
	go func() {
		defer close(clientGone)
		for {
			if _, _, readErr := conn.ReadMessage(); readErr != nil {
				// A malformed frame ends with the RFC protocol-error code; a
				// client close is already echoed inside ReadMessage; a network
				// drop needs no frame.
				var protoErr *wsProtocolErrorString
				if errors.As(readErr, &protoErr) {
					_ = conn.Close(wsCloseProtocolError, "protocol error")
				}
				return
			}
			// Push-only channel: an inbound data frame is read and discarded;
			// the client cannot submit or mutate any operation over it.
		}
	}()

	// endNow maps a closing store to 1001, an active device cancel to 4410
	// and a sticky revoke to 4403, waiting briefly for the peer's close echo.
	// Termination takes precedence over a racing cancel or revoke. It returns
	// true when the subscription must end.
	endNow := func() bool {
		if s.Closing() {
			endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
			return true
		}
		select {
		case <-managed.Canceled():
			endSubscription(conn, clientGone, wsCloseSubscriptionCanceled, "subscription canceled")
			return true
		default:
		}
		select {
		case <-sub.Revoked():
			endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
			return true
		default:
		}
		return false
	}

	// closingOnly honors a termination signal before the first frame; a revoke
	// racing the initial push is left for the main loop so the state that was
	// authorized at handshake still reaches the client ahead of the 4403.
	closingOnly := func() bool {
		if s.Closing() {
			endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
			return true
		}
		return false
	}

	// lastSent skips any queued frame that encodes the same state the
	// connection already sent. Registration-vs-commit atomicity already makes
	// this unnecessary (a queued state is always strictly newer), so this is
	// only a belt-and-braces guard for the register/read boundary.
	var lastSent []byte
	send := func(state crdt.State) bool {
		frame := encodeCRDTStateFrame(state)
		if bytes.Equal(frame, lastSent) {
			return true
		}
		if writeErr := conn.WriteText(frame); writeErr != nil {
			return false
		}
		lastSent = frame
		return true
	}

	// First push: the current merged state. A document with no operation yet
	// stays silent until its first state arrives. A termination signal that
	// raced the registration is honored before anything is sent.
	if closingOnly() {
		return
	}
	if initial != nil {
		if !send(*initial) {
			return
		}
	}

	for {
		if endNow() {
			return
		}

		// Drain every committed state queued since the last park, in commit
		// order; a revoke or termination is honored between frames.
		for _, state := range sub.Drain() {
			if endNow() {
				return
			}
			if !send(state) {
				return
			}
		}
		if endNow() {
			return
		}

		select {
		case <-sub.Wake():
			// A coalescing "drain now" signal; loop and flush the whole queue.
		case <-managed.Canceled():
			if s.Closing() {
				endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
				return
			}
			endSubscription(conn, clientGone, wsCloseSubscriptionCanceled, "subscription canceled")
			return
		case <-sub.Revoked():
			if s.Closing() {
				endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
				return
			}
			endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
			return
		case <-clientGone:
			return
		case <-r.Context().Done():
			return
		}
	}
}

// encodeCRDTStateFrame renders one state message exactly as the state read
// endpoints render their bodies: the shared encoder (HTML escaping included,
// map keys sorted to type then value) and the same trailing newline, so a
// pushed frame can be compared byte-for-byte with a GET .../crdt/state
// response at either the document or session path.
func encodeCRDTStateFrame(state crdt.State) []byte {
	return marshalCRDTState(state)
}

// Package push holds the process-wide, in-memory registry of the live push
// connections — change subscriptions and CRDT state subscriptions alike.
//
// The registry is the management plane behind the device-scoped subscription
// list and cancel endpoints. It owns no durable state: a live entry exists
// exactly while its WebSocket connection does, so a client disconnect, an
// active cancel and a process restart all make the subscription vanish from
// every list immediately. Registration never writes a change, never advances
// a cursor and never writes a CRDT operation.
package push

import (
	"sort"
	"strconv"
	"sync"
	"time"
)

// Kind names one of the two push channels a subscription can ride.
type Kind string

const (
	// KindChanges is the change-log subscription: it replays committed
	// changes past a handshake cursor and fans out later commits.
	KindChanges Kind = "changes"
	// KindState is the CRDT state subscription: it pushes the current merged
	// state and every later merge that actually changes it; it carries no
	// cursor.
	KindState Kind = "state"
)

// Info is the immutable description of one live push connection. Cursor is the
// starting cursor requested at the handshake (0 for a state subscription,
// which has no cursor); EstablishedAt is the connection's establishment time
// as a Unix millisecond timestamp.
type Info struct {
	ID            string
	DeviceID      string
	DocumentID    string
	Kind          Kind
	Cursor        int64
	EstablishedAt int64
	seq           uint64
}

// Subscription is one live registry entry. Its one-shot Canceled channel is
// closed exactly when the device actively cancels this connection through the
// management endpoint; a revoke, a shutdown and a client disconnect never
// close it.
type Subscription struct {
	info       Info
	cancel     chan struct{}
	cancelOnce sync.Once
}

// Info returns the subscription's immutable description.
func (s *Subscription) Info() Info { return s.info }

// Canceled returns the one-shot active-cancel signal.
func (s *Subscription) Canceled() <-chan struct{} { return s.cancel }

// Registry indexes every live push connection in the process. IDs are
// allocated here, so they are unique across both channels for the life of the
// process and are never reused after a connection leaves.
type Registry struct {
	mu   sync.Mutex
	next uint64
	live map[string]*Subscription
}

// NewRegistry returns an empty registry.
func NewRegistry() *Registry {
	return &Registry{live: make(map[string]*Subscription)}
}

// Register records one freshly established push connection and allocates its
// process-unique subscription ID. cursor is the handshake starting cursor for
// a change subscription and must be 0 for a state subscription. The returned
// subscription must be removed with Unregister when the connection ends.
func (r *Registry) Register(deviceID, documentID string, kind Kind, cursor int64) *Subscription {
	r.mu.Lock()
	r.next++
	seq := r.next
	id := formatID(seq)
	sub := &Subscription{
		info: Info{
			ID:            id,
			DeviceID:      deviceID,
			DocumentID:    documentID,
			Kind:          kind,
			Cursor:        cursor,
			EstablishedAt: time.Now().UnixMilli(),
			seq:           seq,
		},
		cancel: make(chan struct{}),
	}
	r.live[id] = sub
	r.mu.Unlock()
	return sub
}

// Unregister removes a connection that has ended. It is idempotent: a client
// disconnect, an active cancel and a shutdown may all race to call it.
func (r *Registry) Unregister(id string) {
	r.mu.Lock()
	delete(r.live, id)
	r.mu.Unlock()
}

// List returns the descriptions of every live connection belonging to
// deviceID, in connection-establishment order (oldest first). Subscriptions
// established by the device directly at the document level and those
// established through sessions it owns all appear, because both flows
// register under the resolved owning device.
func (r *Registry) List(deviceID string) []Info {
	r.mu.Lock()
	out := make([]Info, 0)
	for _, sub := range r.live {
		if sub.info.DeviceID == deviceID {
			out = append(out, sub.info)
		}
	}
	r.mu.Unlock()
	sort.Slice(out, func(i, j int) bool { return out[i].seq < out[j].seq })
	return out
}

// Cancel actively ends the live connection identified by id, but only when it
// currently belongs to deviceID: it removes the entry at once and closes its
// cancel signal, after which the connection layer finishes it with the active
// cancel close code. It returns false without signaling anything when the
// subscription does not exist, has already ended, or belongs to another
// device — those cases are indistinguishable to the caller, which answers
// 404 in every one of them.
func (r *Registry) Cancel(deviceID, id string) bool {
	r.mu.Lock()
	sub, ok := r.live[id]
	if !ok || sub.info.DeviceID != deviceID {
		r.mu.Unlock()
		return false
	}
	// Leave no window in which an already-canceled subscription can still be
	// listed: remove before signaling.
	delete(r.live, id)
	r.mu.Unlock()

	sub.cancelOnce.Do(func() { close(sub.cancel) })
	return true
}

// formatID renders the monotonic sequence as the subscription id. The prefix
// marks the token's origin in logs while the decimal stays unique within the
// process; ids are never reused.
func formatID(seq uint64) string {
	return "sub-" + strconv.FormatUint(seq, 10)
}

