118	func TestDeregisterDeviceHTTPCascade(t *testing.T) {
119		h, _ := newTestHandler(t)
120		registerDevice(t, h, "dev-1")
121		registerDevice(t, h, "dev-2")
122	
123		// dev-1 and dev-2 sessions.
124		w, _ := postJSON(t, h, "/v1/devices/dev-1/sessions", map[string]any{"sessionId": "sess-1"})
125		if w.Code != http.StatusOK {
126			t.Fatal(w.Body.String())
127		}
128		w, _ = postJSON(t, h, "/v1/devices/dev-2/sessions", map[string]any{"sessionId": "sess-2"})
129		if w.Code != http.StatusOK {
130			t.Fatal(w.Body.String())
131		}
132	
133		// dev-1 owns a completed attachment dev-2 is granted access to.
134		content1 := []byte("dev-one bytes")
135		mustCreateAttachment(t, h, "dev-1", "att-1", content1, 8)
136		w, _ = putChunk(t, h, "dev-1", "att-1", 0, content1[:8])
137		if w.Code != http.StatusOK {
138			t.Fatal(w.Body.String())
139		}
140		w, _ = putChunk(t, h, "dev-1", "att-1", 1, content1[8:])
141		if w.Code != http.StatusOK {
142			t.Fatal(w.Body.String())
143		}
144		if w, _ = completeAttachment(t, h, "dev-1", "att-1"); w.Code != http.StatusOK {
145			t.Fatal(w.Body.String())
146		}
147		w, _ = postJSON(t, h, "/v1/devices/dev-1/attachments/att-1/access",
148			map[string]any{"deviceId": "dev-2", "action": "grant"})
149		if w.Code != http.StatusOK {
150			t.Fatal(w.Body.String())
151		}
152		// dev-2 owns an attachment dev-1 is granted access to.
153		content2 := []byte("dev-two bytes!!")
154		mustCreateAttachment(t, h, "dev-2", "att-2", content2, 8)
155		for i, off := 0, 0; off < len(content2); i, off = i+1, off+8 {
156			end := off + 8
157			if end > len(content2) {
158				end = len(content2)
159			}
160			if w, _ = putChunk(t, h, "dev-2", "att-2", int64(i), content2[off:end]); w.Code != http.StatusOK {
161				t.Fatalf("chunk %d: %s", i, w.Body.String())
162			}
