251			t.Fatalf("inherited read grant = %d, want 403", w.Code)
252		}
253		w, body = postJSON(t, h, "/v1/documents/doc/replay", map[string]any{
254			"deviceId": "dev-1",
255			"operations": []any{
256				map[string]any{"id": "c2", "payload": map[string]any{"k2": 2}},
257			},
258		})
