264	func TestDeregisterDeviceHTTPConcurrentAtMostOnce(t *testing.T) {
265		h, _ := newTestHandler(t)
266		registerDevice(t, h, "hot")
267	
268		const n = 40
269		var wg sync.WaitGroup
270		var mu sync.Mutex
271		ok, miss := 0, 0
272		for i := 0; i < n; i++ {
273			wg.Add(1)
274			go func() {
275				defer wg.Done()
276				w := serveRecorder(h, newJSONRequest(http.MethodDelete, "/v1/devices/hot", "", ""))
277				mu.Lock()
278				defer mu.Unlock()
279				switch w.Code {
280				case http.StatusOK:
281					ok++
282				case http.StatusNotFound:
283					miss++
284				default:
285					t.Errorf("status = %d body = %s", w.Code, w.Body.String())
286				}
287			}()
288		}
289		wg.Wait()
290		if ok != 1 || miss != n-1 {
291			t.Fatalf("ok = %d, miss = %d, want 1 and %d", ok, miss, n-1)
292		}
293	
294		// Re-registration after the concurrent cascade is a fresh device.
295		w, body := postJSON(t, h, "/v1/devices", map[string]any{"deviceId": "hot"})
296		if w.Code != http.StatusOK || body["created"] != true {
297			t.Fatalf("re-register = %d %v", w.Code, body)
298		}
299	}
