332		if w.Code != http.StatusOK || body["created"] != true {
333			t.Fatalf("re-register after restart = %d %v", w.Code, body)
334		}
335		w, _ = doRequest(t, h2, http.MethodGet, "/v1/sessions/sess/documents/d/changes")
