342	// device's live change-log and CRDT subscriptions immediately, stickily.
343	func TestDeregisterDeviceHTTPClosesSubscriptions(t *testing.T) {
344		t.Run("change log", func(t *testing.T) {
345			srv, _ := newWSTestServer(t)
346			setupSession(t, srv, "dev-1", "sess", "doc", 1)
347	
348			conn, resp := dialWS(t, subscribeURL(srv, "sess", "doc", "0"))
349			if conn == nil {
