362				t.Fatalf("close code = %d, want 4403", code)
363			}
364			conn.clearReadDeadline()
365	
366			// A reconnect finds the backing session gone: 404 before the upgrade.
367			if _, resp2 := dialWS(t, subscribeURL(srv, "sess", "doc", "0")); resp2.StatusCode != http.StatusNotFound {
368				t.Fatalf("reconnect = %d, want 404", resp2.StatusCode)
369			}
