		 OR EXISTS(SELECT 1 FROM crdt_ops WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM crdt_counter_values WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM crdt_set_elements WHERE document_id = ?)
