		defer conn.close()
		if code := deleteDocumentHTTP(t, srv, "doc", "dev-1"); code != http.StatusOK {
			t.Fatalf("delete = %d", code)
		}
		conn.setReadDeadline(2 * time.Second)
		if code := conn.readCloseCode(); code != 4420 {
			t.Fatalf("close code = %d, want 4420", code)
